    static int ParseAge(string input)
    {
        if (int.TryParse(input, out int age) && age >= 0 && age <= 130)
            return age;
        return -1;              // -1 значит «не разобрали»
    }

    // исключительная ситуация: сообщаем наверх
    static int Divide(int a, int b)
    {
        if (b == 0)
            throw new ArgumentException("деление на ноль");
        return a / b;
    }

    static void Main()
    {
        Console.WriteLine(ParseAge("42"));       // 42
        Console.WriteLine(ParseAge("сорок"));    // -1
        Console.WriteLine(ParseAge("500"));      // -1

        try
        {
            Console.WriteLine(Divide(10, 2));
            Console.WriteLine(Divide(1, 0));
        }
        catch (ArgumentException e)              // ловим конкретный тип
        {
            Console.WriteLine($"поймали: {e.Message}");
        }
        finally
        {
            Console.WriteLine("finally выполняется всегда");
        }
    }
}

