using System;
using System.Collections.Generic;

record Item(string Name, int Price);

class Program
{
    static Dictionary<string, int> Cheapest(List<Item> items)
    {
        var result = new Dictionary<string, int>();
        foreach (var item in items)
        {
            // если имя уже встречалось, оставляем меньшую цену
            if (result.TryGetValue(item.Name, out int known) && known <= item.Price)
                continue;
            result[item.Name] = item.Price;
        }
        return result;
    }

    static string Find(Dictionary<string, int> prices, string name)
    {
        if (prices.TryGetValue(name, out int price))
            return price.ToString();
        return "нет в каталоге";
    }

    static void Main()
    {
        var items = new List<Item>
        {
            new Item("кофе", 25000),
            new Item("чай", 15000),
            new Item("кофе", 21000),
            new Item("чай", 17000),
        };

        var prices = Cheapest(items);
        Console.WriteLine(prices.Count);
        Console.WriteLine(Find(prices, "кофе"));
        Console.WriteLine(Find(prices, "чай"));
        Console.WriteLine(Find(prices, "сок"));
        Console.WriteLine(new Item("кофе", 21000) == new Item("кофе", 21000));
    }
}

