using System;
using System.Collections.Generic;
using System.Linq;

record Order(int UserId, string City, int Amount);
record User(int Id, string Name);

class Program
{
    static void Main()
    {
        var orders = new List<Order>
        {
            new Order(1, "Ташкент", 250), new Order(2, "Бухара", 100),
            new Order(1, "Ташкент", 400), new Order(3, "Самарканд", 180),
        };
        var users = new List<User> { new User(1, "Азиз"), new User(2, "Дилноза") };

        // GROUP BY city
        var byCity = orders
            .GroupBy(o => o.City)
            .Select(g => new { City = g.Key, Total = g.Sum(o => o.Amount), Count = g.Count() })
            .OrderByDescending(x => x.Total)
            .ThenBy(x => x.City);

        foreach (var row in byCity)
            Console.WriteLine($"{row.City}: {row.Total} ({row.Count} заказ.)");

        // INNER JOIN orders ON users
        var named = orders.Join(
            users,
            o => o.UserId,
            u => u.Id,
            (o, u) => new { u.Name, o.Amount });

        Console.WriteLine("--- с именами ---");
        foreach (var row in named)
            Console.WriteLine($"{row.Name}: {row.Amount}");

        Console.WriteLine($"средний чек: {orders.Average(o => o.Amount)}");
        Console.WriteLine($"максимум: {orders.Max(o => o.Amount)}");
    }
}

