using System;
using System.Collections.Generic;

abstract record Shape;
record Sq(double Side) : Shape;
record Rect(double W, double H) : Shape;
record Circle(double R) : Shape;

record Order(string City, int Amount);

class Program
{
    // switch-выражение по типу: короче и полнее, чем цепочка if
    static double Area(Shape s) => s switch
    {
        Sq q => q.Side * q.Side,
        Rect r => r.W * r.H,
        Circle c => Math.Round(3.14159 * c.R * c.R, 2),
        _ => 0,
    };

    // сопоставление по свойствам и условиям
    static string Grade(Order o) => o switch
    {
        { Amount: > 300 } and { City: "Ташкент" } => "крупный столичный",
        { Amount: > 300 } => "крупный",
        { Amount: > 100 } => "средний",
        _ => "мелкий",
    };

    static string Describe(object x) => x switch
    {
        int n when n < 0 => $"отрицательное {n}",
        int n => $"число {n}",
        string s => $"строка длиной {s.Length}",
        null => "пусто",
        _ => "что-то ещё",
    };

    static void Main()
    {
        var shapes = new List<Shape> { new Sq(3), new Rect(2, 5), new Circle(1) };
        foreach (var s in shapes) Console.WriteLine($"{s.GetType().Name}: {Area(s)}");

        Console.WriteLine(Grade(new Order("Ташкент", 400)));
        Console.WriteLine(Grade(new Order("Бухара", 400)));
        Console.WriteLine(Grade(new Order("Бухара", 50)));

        Console.WriteLine(Describe(42));
        Console.WriteLine(Describe(-7));
        Console.WriteLine(Describe("привет"));
        Console.WriteLine(Describe(null));
    }
}

