        var orders = new List<Order>
        {
            new Order(1, 250), new Order(2, 100), new Order(1, 400),
            new Order(3, 180), new Order(2, 80),
        };
        var users = new List<User>
        {
            new User(1, "Ташкент"), new User(2, "Бухара"), new User(3, "Самарканд"),
        };

        var report = orders
            .Join(users, o => o.UserId, u => u.Id, (o, u) => new { u.City, o.Amount })
            .GroupBy(x => x.City)
            .Select(g => new { City = g.Key, Total = g.Sum(x => x.Amount) })
            .OrderByDescending(x => x.Total)
            .ThenBy(x => x.City)
            .ToList();

        foreach (var row in report)
            Console.WriteLine($"{row.City}: {row.Total} {Size(row.Total)}");
    }
}
